'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepEqual(Object.keys(api).sort(), ['createInitialQueueState', 'reduceQueue']);
const { createInitialQueueState, reduceQueue } = api;

const initialA = createInitialQueueState();
const initialB = createInitialQueueState();
assert.deepEqual(initialA, { active: false, jobs: [], fault: null });
assert.notStrictEqual(initialA, initialB);
assert.notStrictEqual(initialA.jobs, initialB.jobs);
assert.deepEqual(reduceQueue(undefined, null), { active: false, jobs: [], fault: null });

for (const bad of [null, {}, { active: 0, jobs: [], fault: null },
  { active: false, jobs: null, fault: null }, { active: false, jobs: [] }]) {
  assert.throws(() => reduceQueue(bad, { type: 'FINISH' }), TypeError);
}

const state = { active: false, jobs: [{ id: 'a', value: 1 }], fault: 'old' };
for (const event of [null, [], {}, { type: 4 }, { type: 'UNKNOWN' }]) {
  assert.strictEqual(reduceQueue(state, event), state);
}

const begun = reduceQueue(state, { type: 'BEGIN' });
assert.deepEqual(begun, { active: true, jobs: state.jobs, fault: null });
assert.notStrictEqual(begun, state);
assert.strictEqual(begun.jobs, state.jobs);

const failurePayload = { message: 'bad' };
const failed = reduceQueue(begun, { type: 'FAILED', payload: failurePayload });
assert.equal(failed.active, false);
assert.strictEqual(failed.fault, failurePayload);
assert.strictEqual(failed.jobs, begun.jobs);

const finished = reduceQueue(begun, { type: 'FINISH' });
assert.deepEqual(finished, { active: false, jobs: begun.jobs, fault: begun.fault });
assert.notStrictEqual(finished, begun);

for (const type of ['ENQUEUE', 'REPLACE']) {
  for (const payload of [undefined, null, [], {}, { id: 1 }]) {
    assert.throws(() => reduceQueue(state, { type, payload }), TypeError);
  }
}

const payload = { id: 'b', value: { nested: true } };
const event = { type: 'ENQUEUE', payload };
const enqueued = reduceQueue(state, event);
assert.deepEqual(enqueued.jobs, [state.jobs[0], payload]);
assert.notStrictEqual(enqueued.jobs, state.jobs);
assert.strictEqual(enqueued.jobs[0], state.jobs[0]);
assert.notStrictEqual(enqueued.jobs[1], payload);
assert.strictEqual(enqueued.jobs[1].value, payload.value);
assert.deepEqual(state, { active: false, jobs: [{ id: 'a', value: 1 }], fault: 'old' });
assert.deepEqual(event, { type: 'ENQUEUE', payload });

assert.strictEqual(reduceQueue(enqueued, { type: 'ENQUEUE', payload: { id: 'b', value: 9 } }), enqueued);
assert.strictEqual(reduceQueue(enqueued, { type: 'REPLACE', payload: { id: 'missing' } }), enqueued);

const replacement = { id: 'a', value: 7 };
const replaced = reduceQueue(enqueued, { type: 'REPLACE', payload: replacement });
assert.deepEqual(replaced.jobs, [{ id: 'a', value: 7 }, { id: 'b', value: payload.value }]);
assert.notStrictEqual(replaced.jobs[0], replacement);
assert.strictEqual(replaced.jobs[1], enqueued.jobs[1]);
assert.deepEqual(enqueued.jobs[0], { id: 'a', value: 1 });

